using System;
using System.Collections.Generic;
using System.IO;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Media;

internal sealed class RiftSettingsPane:Grid {
    readonly EnergyOverlay owner;readonly Window window;readonly StackPanel controls=new StackPanel();readonly Image counter=new Image{Height=92,Stretch=Stretch.Uniform};
    readonly ComboBox region=new ComboBox{Width=220,Height=34};readonly TextBlock state=SettingsVisual.Text("",12,"#C4A1EC");readonly Slider seconds=new Slider{Minimum=0,Maximum=600,Value=599,TickFrequency=1,IsSnapToTickEnabled=true};
    readonly Dictionary<string,SettingsNumber> numbers=new Dictionary<string,SettingsNumber>();readonly List<Action<RiftOptions>> reloaders=new List<Action<RiftOptions>>();readonly RiftCounterPaint paint=new RiftCounterPaint();
    RiftOptions saved;string language;bool loading,released,savedEnabled;int previewSeconds=-1;
    internal RiftSettingsPane(EnergyOverlay owner,Window window){this.owner=owner;this.window=window;Children.Add(controls);controls.Children.Add(SettingsVisual.Text("SPACETIME RIFT SETTINGS",14,"#C4A1EC"));
        var group=Group("SERVER REGION");var row=Row("Schedule region");Grid.SetColumn(region,1);row.Children.Add(region);group.Children.Add(row);foreach(string label in RiftCalendar.Labels)region.Items.Add(new ComboBoxItem{Content=label});group.Children.Add(state);group.Children.Add(SettingsVisual.Text("Uses the character's server region. Your local clock and daylight saving are handled automatically. If detection is unavailable, select the region where you play.",11,"#8994A6"));
        group=Group("RIFT NOTIFICATIONS");Number(group,"Lead","Minutes before opening","min",1,10,o=>o.LeadMinutes,(o,v)=>o.LeadMinutes=v);
        var tests=new StackPanel{Orientation=Orientation.Horizontal};reloaders.Add(o=>tests.IsEnabled=owner.Configuration.Notifications.Enabled);tests.Children.Add(SettingsVisual.Button("Test opening alert",delegate{owner.TestRift(true);}));var reminder=SettingsVisual.Button("Test advance reminder",delegate{owner.TestRift(false);});reminder.Margin=new Thickness(8,0,0,0);tests.Children.Add(reminder);var closing=SettingsVisual.Button("Test closing alert",delegate{owner.TestRift(false,true);});closing.Margin=new Thickness(8,0,0,0);tests.Children.Add(closing);group.Children.Add(tests);group.Children.Add(SettingsVisual.Text("Rift alerts use the shared notification appearance and sound. Enable all notifications must also be on.",11,"#8994A6"));
        group=Group("PORTAL COUNTDOWN");Check(group,"Show portal countdown",o=>o.Counter.Enabled,(o,v)=>o.Counter.Enabled=v);group.Children.Add(counter);var previewRow=Row("Preview seconds remaining");seconds.Width=220;Grid.SetColumn(seconds,1);previewRow.Children.Add(seconds);group.Children.Add(previewRow);group.Children.Add(SettingsVisual.Text("An independent widget shown during the 10-minute entry window. Opening the helper partway through shows the actual scheduled time remaining. Unlock widgets in General to move it; dragging its edges changes the whole scale.",11,"#8994A6"));
        group=Group("APPEARANCE");Number(group,"Scale","Whole widget scale","%",50,300,o=>o.Counter.ScalePercent,(o,v)=>o.Counter.ScalePercent=v);Number(group,"Font","Countdown text size","px",12,48,o=>o.Counter.FontSize,(o,v)=>o.Counter.FontSize=v);Check(group,"Icon glow",o=>o.Counter.IconGlow,(o,v)=>o.Counter.IconGlow=v);Number(group,"Glow","Glow intensity","%",0,100,o=>o.Counter.GlowPercent,(o,v)=>o.Counter.GlowPercent=v);Number(group,"Background","Background opacity","%",0,100,o=>(int)Math.Round(o.Counter.BackgroundOpacity*100/255.0),(o,v)=>o.Counter.BackgroundOpacity=(int)Math.Round(v*255/100.0));Number(group,"Opacity","Widget opacity","%",0,100,o=>o.Counter.Opacity,(o,v)=>o.Counter.Opacity=v);Check(group,"Black text outline",o=>o.Counter.Outline,(o,v)=>o.Counter.Outline=v);Number(group,"Outline","Outline thickness","px",1,4,o=>o.Counter.OutlineWidth,(o,v)=>o.Counter.OutlineWidth=v);
        row=Row("Countdown color");var color=SettingsVisual.Button("Choose color",delegate{var picker=new HelperColorPicker(owner.Configuration.Notifications.Rift.Counter.Color,"Countdown color",owner.Language){Owner=window};if(picker.ShowDialog()==true)Change(o=>o.Counter.Color=picker.SelectedHex);});Grid.SetColumn(color,1);row.Children.Add(color);group.Children.Add(row);reloaders.Add(o=>{color.Content=new Border{Background=SettingsVisual.Brush(o.Counter.Color),Width=110,Height=16};color.IsEnabled=o.Counter.Enabled;});
        group=Group("POSITION & SIZE");Number(group,"X","Horizontal position","px",-100000,100000,o=>o.Counter.Bounds.X,(o,v)=>{var b=o.Counter.Bounds;b.X=v;o.Counter.Bounds=b;});Number(group,"Y","Vertical position","px",-100000,100000,o=>o.Counter.Bounds.Y,(o,v)=>{var b=o.Counter.Bounds;b.Y=v;o.Counter.Bounds=b;});Number(group,"Width","Width","px",260,900,o=>o.Counter.Bounds.Width,(o,v)=>{var b=o.Counter.Bounds;int center=b.X+b.Width/2;b.Width=v;b.X=center-v/2;o.Counter.Bounds=b;});
        controls.Children.Add(SettingsVisual.Text("Scheduled openings based on a community timetable; not confirmation of a portal detected in the game. The countdown measures entry availability, not the duration of the event after entering.",11,"#B1A3BC"));
        region.SelectionChanged+=delegate{if(region.SelectedIndex>=0)Change(o=>o.Region=RiftCalendar.Keys[region.SelectedIndex]);};seconds.ValueChanged+=delegate{if(!loading)Reload();};Reload();
    }
    Grid Row(string text){var row=new Grid{Margin=new Thickness(0,5,0,5),MinHeight=35};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(SettingsVisual.Text(text));return row;}
    StackPanel Group(string title){controls.Children.Add(SettingsVisual.Text(title,10,"#929CAD"));var group=new StackPanel();var card=SettingsVisual.Card(group,new Thickness(16,8,16,8));card.Margin=new Thickness(0,6,0,16);controls.Children.Add(card);return group;}
    void Change(Action<RiftOptions> action){if(loading||released)return;var cfg=owner.Configuration;action(cfg.Notifications.Rift);cfg.Notifications.Rift.Normalize();owner.ApplyConfiguration(cfg);}
    void Check(StackPanel group,string label,Func<RiftOptions,bool> get,Action<RiftOptions,bool> set){var row=Row(label);var toggle=new CheckBox();AutomationProperties.SetName(toggle,label);Grid.SetColumn(toggle,1);row.Children.Add(toggle);group.Children.Add(row);toggle.Click+=delegate{Change(o=>set(o,toggle.IsChecked==true));};reloaders.Add(o=>{toggle.IsChecked=get(o);if(label=="Icon glow"||label=="Black text outline")toggle.IsEnabled=o.Counter.Enabled;});}
    void Number(StackPanel group,string key,string label,string unit,int min,int max,Func<RiftOptions,int> get,Action<RiftOptions,int> set){var row=Row(label);var holder=new StackPanel{Orientation=Orientation.Horizontal};var input=new SettingsNumber(label,min,max,0,1);numbers[key]=input;holder.Children.Add(input);holder.Children.Add(SettingsVisual.Text(unit,11,"#8994A6"));Grid.SetColumn(holder,1);row.Children.Add(holder);group.Children.Add(row);input.Changed+=delegate{Change(o=>set(o,(int)input.Value));};reloaders.Add(o=>{input.Value=get(o);input.IsEnabled=key=="Lead"?o.Warning&&owner.Configuration.Notifications.Enabled:o.Counter.Enabled;if(key=="Glow")input.IsEnabled&=o.Counter.IconGlow;if(key=="Outline")input.IsEnabled&=o.Counter.Outline;});}
    internal void UpdateStatus(){string text=owner.RiftDescription;if(state.Text!=text)state.Text=text;}
    internal void Reload(){if(released)return;var notification=owner.Configuration.Notifications;var o=notification.Rift;bool same=saved!=null&&RiftOptions.Same(saved,o)&&language==owner.Language&&savedEnabled==notification.Enabled;
        if(same&&previewSeconds==(int)seconds.Value){UpdateStatus();return;}loading=true;try{region.SelectedIndex=Array.IndexOf(RiftCalendar.Keys,o.Region);foreach(var load in reloaders)load(o);
            if(!same||previewSeconds!=(int)seconds.Value){int value=(int)seconds.Value;using(var bitmap=paint.Render(o.Counter,owner.Language,(value/60).ToString("00")+":"+(value%60).ToString("00"),false)){counter.Source=SettingsVisual.Bitmap(bitmap);counter.Height=Math.Min(180,bitmap.Height);}counter.Opacity=o.Counter.Opacity/100.0;}
            if(language!=owner.Language)UiLanguage.Apply(this,owner.Language);language=owner.Language;saved=o.Copy();savedEnabled=notification.Enabled;previewSeconds=(int)seconds.Value;UpdateStatus();
        }finally{loading=false;}}
    internal void Release(){released=true;counter.Source=null;paint.Dispose();}
    internal void Verify(string root){var original=owner.Configuration;var cfg=original.Copy();cfg.Notifications.Rift.Region="eu";owner.ApplyConfiguration(cfg);Reload();var image=counter.Source;for(int i=0;i<100;i++)Reload();if(!object.ReferenceEquals(image,counter.Source))throw new Exception("Unchanged Rift preview must remain cached");numbers["Scale"].Value=150;Change(o=>o.Counter.ScalePercent=150);Reload();if(owner.Configuration.Notifications.Rift.Counter.ScalePercent!=150)throw new Exception("Rift scale persistence");owner.UndoConfiguration();if(owner.Configuration.Notifications.Rift.Counter.ScalePercent!=original.Notifications.Rift.Counter.ScalePercent)throw new Exception("Rift settings undo");owner.ApplyConfiguration(original);Reload();}
}
